import json
from pyhelpers import normalize_keys, top_k, summarize, tokenize

def run(data_path, out_path):
    with open(data_path, 'r') as f:
        data = json.load(f)

    normalizedKeys = {
        "mapping": normalize_keys(data["normalizedKeys"]["mapping"], case='ascii')
    }

    topIds = {
        "ids": sorted([record["id"] for record in top_k(data["topIds"]["records"], k=data["topIds"]["k"], key=lambda x: x[data["topIds"]["key"]])])
    }

    summaries = {
        "summaries": {name: summarize(values) for name, values in data["summaries"]["series"].items()}
    }

    tokenCounts = {
        "tokenCounts": [len(tokenize(line, sep=data["tokenCounts"]["sep"])) for line in data["tokenCounts"]["lines"]]
    }

    result = {
        **normalizedKeys,
        **topIds,
        **summaries,
        **tokenCounts
    }

    with open(out_path, 'w') as f:
        json.dump(result, f, indent=4)

